const front = $('Vagas Frontend BR').all().map(x => x.json).flatMap(x => Array.isArray(x) ? x : [x]);
const back = $('Vagas Backend BR').all().map(x => x.json).flatMap(x => Array.isArray(x) ? x : [x]);
const remoteRaw = $('Vagas Remotas Himalayas').all().map(x => x.json).flatMap(x => Array.isArray(x) ? x : [x]);
const remoteJobs = Array.isArray(remoteRaw) && remoteRaw[0] && Array.isArray(remoteRaw[0].jobs) ? remoteRaw[0].jobs : [];
const nowIso = new Date().toISOString();
const maxHistoric = 400;
const sourceNames = ['Frontend BR', 'Backend BR', 'Himalayas'];
const stripVolatile = (value) => {
  if (!value || typeof value !== 'object') return value;
  const next = { ...value };
  delete next.ultimaSincronizacao;
  delete next.ultimaConsultaBemSucedida;
  delete next.statusExecucao;
  delete next.novasNaExecucao;
  delete next.historicoPreservado;
  delete next.limiteHistorico;
  delete next.ultimaSincronizacaoCompleta;
  delete next.ultimaSincronizacaoParcial;
  return next;
};
const normalizeIssue = (item, source) => {
  if (!item || !item.id) return null;
  const title = String(item.title || '').trim();
  const body = String(item.body || '');
  const now = nowIso;
  return {
    id: `${source.toLowerCase().replace(/\W+/g, '-')}-${item.id}`,
    cargo: title,
    empresa: 'Ver anúncio',
    nivel: /est[aá]gio|intern|aprendiz|trainee/i.test(title + ' ' + body) ? 'Estágio' : 'Júnior',
    modalidade: /remot|home\.?office/i.test(title + ' ' + body) ? 'Remoto' : (/h[ií]brid/i.test(title + ' ' + body) ? 'Híbrido' : 'Não informada'),
    local: 'Brasil / ver anúncio',
    descricao: body.slice(0, 500),
    publicadoEm: item.created_at || '',
    fonte: source,
    link: item.html_url || '',
    capturadoEm: now,
    primeiraIdentificacao: now,
    ultimaIdentificacao: now,
    statusIdentificacao: 'nova'
  };
};
const normalizeHimalayas = (item) => {
  if (!item || !item.id && !item.guid) return null;
  const title = String(item.title || item.cargo || '');
  const company = String(item.companyName || item.empresa || 'Não informada');
  const now = nowIso;
  return {
    id: item.id || `himalayas-${String(item.guid || item.applicationLink || title).replace(/\W+/g, '-') }`,
    cargo: title,
    empresa: company,
    nivel: /est[aá]gio|intern|aprendiz|trainee/i.test(title) ? 'Estágio' : 'Júnior',
    modalidade: 'Remoto',
    local: Array.isArray(item.locationRestrictions) && item.locationRestrictions.length ? 'Brasil' : 'Mundial (ver restrições)',
    descricao: String(item.excerpt || item.description || '').slice(0, 500),
    publicadoEm: item.pubDate || item.publicadoEm || '',
    expiraEm: item.expiryDate || item.expiraEm || '',
    fonte: 'Himalayas',
    link: item.applicationLink || item.link || '',
    capturadoEm: now,
    primeiraIdentificacao: now,
    ultimaIdentificacao: now,
    statusIdentificacao: 'nova'
  };
};
function normalizeUrl(raw) {
  if (!raw) return '';
  const value = String(raw).trim();
  if (!/^https?:\/\//i.test(value)) return value;
  try {
    const url = new URL(value);
    url.hash = '';
    const params = new URLSearchParams(url.search);
    const tracking = new Set(['utm_source','utm_medium','utm_campaign','utm_term','utm_content','utm_id','gclid','fbclid','mc_cid','mc_eid']);
    for (const key of [...params.keys()]) {
      if (tracking.has(String(key).toLowerCase())) params.delete(key);
    }
    url.search = params.toString();
    return String(url).replace(/[?#]+$/, '');
  } catch (e) {
    return value.replace(/[?&](?:utm_[^&]+|gclid|fbclid|mc_cid|mc_eid)=[^&]+/gi, '').replace(/&&+/g, '&').replace(/[?&]$/, '');
  }
}
function normalizeCompany(value) {
  return String(value || '')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\b(?:ltda|ltda\.|sa|s\.a\.|s\/a|inc|corp|company|consultoria|brasil|do brasil)\b/gi, '')
    .replace(/[^A-Za-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}
function normalizeRole(value) {
  return String(value || '')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\b(full[\s-]?stack)\b/gi, 'fullstack')
    .replace(/\b(front[\s-]?end)\b/gi, 'frontend')
    .replace(/\b(back[\s-]?end)\b/gi, 'backend')
    .replace(/\b(junior|júnior|jr|estagi[oá]rio|est[aá]gio|intern(ship)?|trainee|entry[\s-]?level)\b/gi, '')
    .replace(/[^A-Za-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}
const incoming = [
  ...front.filter(Boolean).map(item => normalizeIssue(item, 'Frontend BR')),
  ...back.filter(Boolean).map(item => normalizeIssue(item, 'Backend BR')),
  ...remoteJobs.filter(Boolean).map(normalizeHimalayas)
].filter(Boolean);
const githubFile = $input.first().json;
if (!githubFile || !githubFile.sha || !githubFile.content) {
  throw new Error('Arquivo data/vagas.json não encontrado no repositório.');
}
const existingJson = JSON.parse(Buffer.from(githubFile.content, 'base64').toString('utf8'));
const current = Array.isArray(existingJson.vagas) ? existingJson.vagas : [];
const existingById = new Map(current.map(v => [v.id, v]));
const urlIndex = new Map();
for (const item of current) {
  const url = normalizeUrl(item.link || item.url || item.html_url || item.applicationLink || '');
  if (url) urlIndex.set(url, item);
}
const merged = new Map();
const sourceStats = {};
for (const name of sourceNames) { sourceStats[name] = false; }
for (const item of incoming) {
  const url = normalizeUrl(item.link || item.url || item.html_url || item.applicationLink || '');
  let match = existingById.get(item.id);
  if (!match && url) match = urlIndex.get(url);
  if (match) {
    const mergedItem = { ...match, ...item };
    mergedItem.ultimaIdentificacao = nowIso;
    if (!mergedItem.primeiraIdentificacao) mergedItem.primeiraIdentificacao = match.capturadoEm || nowIso;
    mergedItem.urlNormalizada = url || match.urlNormalizada || normalizeUrl(match.link || match.url || match.html_url || match.applicationLink || '');
    mergedItem.empresaNormalizada = normalizeCompany(mergedItem.empresa || match.empresa || '');
    mergedItem.cargoNormalizado = normalizeRole(mergedItem.cargo || match.cargo || '');
    mergedItem.fontesAlternativas = Array.from(new Set([...(Array.isArray(match.fontesAlternativas) ? match.fontesAlternativas : []), ...(Array.isArray(item.fontesAlternativas) ? item.fontesAlternativas : []), match.fonte, item.fonte].filter(Boolean)));
    merged.set(mergedItem.id, mergedItem);
  } else {
    const candidate = { ...item };
    candidate.urlNormalizada = url;
    candidate.empresaNormalizada = normalizeCompany(candidate.empresa);
    candidate.cargoNormalizado = normalizeRole(candidate.cargo);
    candidate.fontesAlternativas = [candidate.fonte].filter(Boolean);
    candidate.primeiraIdentificacao = candidate.primeiraIdentificacao || nowIso;
    candidate.ultimaIdentificacao = nowIso;
    candidate.statusIdentificacao = 'nova';
    merged.set(candidate.id, candidate);
  }
}
for (const existing of current) {
  if (!existing || !existing.id) continue;
  if (!merged.has(existing.id)) {
    const clone = { ...existing };
    clone.primeiraIdentificacao = clone.primeiraIdentificacao || clone.capturadoEm || nowIso;
    clone.ultimaIdentificacao = clone.ultimaIdentificacao || clone.primeiraIdentificacao || nowIso;
    clone.statusIdentificacao = clone.statusIdentificacao || 'existente';
    clone.urlNormalizada = normalizeUrl(clone.link || clone.url || clone.html_url || clone.applicationLink || '');
    clone.empresaNormalizada = normalizeCompany(clone.empresa || '');
    clone.cargoNormalizado = normalizeRole(clone.cargo || '');
    clone.fontesAlternativas = Array.isArray(clone.fontesAlternativas) ? clone.fontesAlternativas : [clone.fonte].filter(Boolean);
    merged.set(existing.id, clone);
  }
}
const proposal = Array.from(merged.values())
  .filter(Boolean)
  .map(v => ({ ...v, publicadoEm: v.publicadoEm || '', urlNormalizada: normalizeUrl(v.link || v.url || v.html_url || v.applicationLink || ''), empresaNormalizada: normalizeCompany(v.empresa || ''), cargoNormalizado: normalizeRole(v.cargo || '') }))
  .sort((a, b) => new Date(b.ultimaIdentificacao || b.publicadoEm || b.capturadoEm || 0).getTime() - new Date(a.ultimaIdentificacao || a.publicadoEm || a.capturadoEm || 0).getTime())
  .slice(0, maxHistoric);
const comparableCurrent = current.map(stripVolatile).map(item => ({ ...item, link: normalizeUrl(item.link || item.url || item.html_url || item.applicationLink || ''), urlNormalizada: normalizeUrl(item.link || item.url || item.html_url || item.applicationLink || '') }));
const comparableProposal = proposal.map(stripVolatile).map(item => ({ ...item, link: normalizeUrl(item.link || item.url || item.html_url || item.applicationLink || ''), urlNormalizada: normalizeUrl(item.link || item.url || item.html_url || item.applicationLink || '') }));
const changedRelevant = JSON.stringify(comparableCurrent) !== JSON.stringify(comparableProposal);
const payload = {
  atualizadoEm: nowIso,
  total: proposal.length,
  vagas: proposal,
  ultimaSincronizacao: nowIso,
  ultimaSincronizacaoCompleta: Array.isArray(incoming) && incoming.length ? nowIso : null,
  ultimaSincronizacaoParcial: null,
  limiteHistorico: maxHistoric,
  historicoPreservado: true,
  novasNaExecucao: proposal.filter(v => v.statusIdentificacao === 'nova').length
};
const shouldPublish = changedRelevant && proposal.length > 0;
return [{
  json: {
    changed: shouldPublish,
    relevantChange: changedRelevant,
    total: proposal.length,
    novos: payload.novasNaExecucao,
    sha: githubFile.sha,
    content: shouldPublish ? Buffer.from(JSON.stringify(payload, null, 2) + '\n', 'utf8').toString('base64') : null,
    preserveHistory: true
  }
}];

const status = $input.first().json.statusCode;
const body = $input.first().json.body || {};
const message = body && body.message ? String(body.message) : '';
const conflict = status === 409 || status === 422;
return [{ json: { statusCode: status, conflict, message, shouldRetry: conflict, publicationAttempted: true } }];
